<script lang="ts">import type{MessageLive,MessageTone}from'@fex-design/core/message/types';import{messageStatusClassName}from'@fex-design/styles/message';import{cn}from'@fex/utils';import type{Snippet}from'svelte';import type{HTMLAttributes}from'svelte/elements';interface Props extends HTMLAttributes<HTMLDivElement>{tone?:MessageTone;live?:MessageLive;children?:Snippet}let{tone='neutral',live='polite',class:className,children,...rest}:Props=$props()</script><div {...rest} data-slot="message-status" data-tone={tone} role={live==='off'?undefined:'status'} aria-live={live==='off'?undefined:live} class={cn(messageStatusClassName({tone}),className)}>{@render children?.()}</div>
